def stats(x,rng,B=10000):
 x=np.array(x,dtype=float);boot=rng.choice(x,size=(B,len(x)),replace=True).mean(axis=1)
 return {'n':len(x),'mean':float(x.mean()),'median':float(np.median(x)),'std':float(x.std(ddof=1)),'CV':float(x.std(ddof=1)/abs(x.mean())) if x.mean()!=0 else None,'MAD':float(np.median(abs(x-np.median(x)))),'variance':float(x.var(ddof=1)),'bootstrap_95CI_mean':np.quantile(boot,[.025,.975]).tolist()}
