  def hierarchical(a,b):
   items=rng.integers(0,a.shape[1],size=(B,5,a.shape[1]));return (b[runs_ix[:,:,None],items].mean(axis=2)/a[runs_ix[:,:,None],items].mean(axis=2)).mean(axis=1)
  dboot=hierarchical(a1,b1)-hierarchical(a2,b2);dci=np.quantile(dboot,[.025,.975]);sdboot=np.sqrt((x[runs_ix].var(axis=1,ddof=1)+y[runs_ix].var(axis=1,ddof=1))/2);excess=abs(dboot)-sdboot;excessci=np.quantile(excess,[.025,.975]);orig=t['Delta_S'];sign=float(np.mean(delta*orig>0));row={'anchor':anchor['anchor'],'model':t['model'],'co_model':t['co_model'],'task_a':t['task_a'],'task_b':t['task_b'],'original_9A1_Delta_S':orig,'mean_Delta_S':mean,'median_Delta_S':float(np.median(delta)),'bootstrap_95CI_low':float(dci[0]),'bootstrap_95CI_high':float(dci[1]),'CI_excludes_zero':bool(dci[0]>0 or dci[1]<0),'sign_consistency':sign,'repetition_Delta_S':delta.tolist(),'standardized_effect_size':mean/pooled if pooled else None,'matched_input_mean_Delta_S':float(np.mean((b1/a1).mean(axis=1)-(b2/a2).mean(axis=1))),'effect_minus_pooled_std_95CI':excessci.tolist()};effects.append(row);boots[anchor['anchor']]={'aggregate':row,'hierarchical_bootstrap_rule':p['bootstrap'],'process_block_mean_Delta_CI':np.quantile(delta[runs_ix].mean(axis=1),[.025,.975]).tolist()};snr[anchor['anchor']]={'SNR_effect':abs(mean)/pooled if pooled else None,'between_task_variance':between,'within_state_variance':within,'variance_ratio':between/within if within else None,'pooled_within_state_std':pooled,'no_magic_cutoff':True}
