def historical_audit(anchor,runs,p):
 pool={r['pool_id']:r for r in [json.loads(s) for s in Path(p['input_pool']).read_text().splitlines() if s.strip()]};records=[];runinfo=[];co_overlaps=[]
 from joint_deploy.run_active_pair_profile import merge_intervals,overlap_with_union
 for source in anchor['historical_runs']:
  raw=load(source['raw_path']);targets=[r for r in raw['request_records'] if r['model_family']=='phi4mm' and r['task']=='asr'];intervals=merge_intervals([(r['worker_response']['start_ns'],r['worker_response']['end_ns']) for r in raw['request_records'] if r['model_family']!='phi4mm' and r.get('worker_response') and r['status']=='completed'])
  for order,r in enumerate(targets):
   item=pool[r['pool_id']]['sample'];response=r['worker_response'];overlap=overlap_with_union(response['start_ns'],response['end_ns'],intervals)/(response['end_ns']-response['start_ns']);co_overlaps.append(overlap);records.append({'historical_raw_id':source['physical_raw_id'],'sample_id':r['pool_id'],'audio_duration_seconds':item.get('duration_s'),'prediction_word_count':len(response['prediction'].split()),'reference_word_count':response.get('reference_words'),'worker_latency_ms':r['worker_latency_ms'],'queue_wait_ms':r['worker_queue_wait_ms'],'arrival_delay_ms':r['schedule_delay_ms'],'arrival_offset_seconds':(r['scheduled_time_ns']-raw['measurement_window']['start_time_ns'])/1e9,'target_request_order':order,'co_worker_active_overlap':overlap})
  target_times=[r['worker_response']['start_ns'] for r in targets]
  outstanding=[]
  for stamp in target_times:
   outstanding.append({m:sum(q['actual_submit_unix_ns']<=stamp<q['worker_response']['end_ns'] for q in raw['request_records'] if q['model']==m and q.get('worker_response')) for m in raw['transport_deployment']})
  ms=raw['measurement_window'];telemetry=[v for v in raw['telemetry']['samples'] if ms['start_unix_ns']<=v['unix_ns']<=ms['start_unix_ns']+210*10**9]
  runinfo.append({'raw_id':source['physical_raw_id'],'target_count':len(targets),'target_sample_IDs':[r['pool_id'] for r in targets],'mean_latency_ms':float(np.mean([r['worker_latency_ms'] for r in targets])),'mean_audio_duration_seconds':float(np.mean([pool[r['pool_id']]['sample']['duration_s'] for r in targets])),'mean_prediction_words':float(np.mean([len(r['worker_response']['prediction'].split()) for r in targets])),'startup_ready_provenance':raw['worker_identities'],'warmup_status':raw['warmup']['status_counts'],'warmup_duration_seconds':raw['warmup']['duration_seconds'],'historical_telemetry_available_fields':list(raw['telemetry']['samples'][0]),'pending_submitted_requests_at_target_start':outstanding,'measurement_GPU_utilization_percent':{'mean':float(np.mean([v['gpu_util_percent'] for v in telemetry])),'min':min(v['gpu_util_percent'] for v in telemetry),'max':max(v['gpu_util_percent'] for v in telemetry)},'first_target_is_cold_start_request':False,'first_target_caveat':'ASR path had native priming before warmup; first target occurs tens of seconds into the measurement window. First-vs-second target latency is confounded by different input IDs and cannot isolate startup effects.','exact_historical_READY_startup_latency':'UNAVAILABLE; worker identities and load-phase telemetry are preserved'})
 durations=[r['audio_duration_seconds'] for r in records];lengths=[r['prediction_word_count'] for r in records];latencies=[r['worker_latency_ms'] for r in records];durcorr=spearmanr(durations,latencies);lencorr=spearmanr(lengths,latencies);ids=[r['sample_id'] for r in records];fresh=runs['historical_phi_asr_full'];stand=runs['historical_phi_asr_none'];ratio=[np.mean([v['worker_latency_ms'] for v in a['target_records']])/np.mean([v['worker_latency_ms'] for v in b['target_records']]) for a,b in zip(fresh,stand)]
 diagnostic={'new_fixed_input_full_replay':{'S_run':list(map(float,ratio)),'sigma_within':float(np.std(ratio,ddof=1)),'latency_run_means_ms':[float(np.mean([v['worker_latency_ms'] for v in r['target_records']])) for r in fresh],'clock_thermal_sample_count':sum(len(r['clock_thermal_diagnostics']) for r in fresh)},'historical':{'floor':anchor['historical_noise_driver']['bootstrap_null_abs_deltaS_p95'],'latency_CV':anchor['historical_noise_driver']['latency_cv'],'records':records,'runs':runinfo,'all_six_target_samples_distinct':len(set(ids))==len(ids),'duration_latency_spearman_descriptive':float(durcorr.statistic),'prediction_words_latency_spearman_descriptive':float(lencorr.statistic),'max_queue_wait_ms':max(r['queue_wait_ms'] for r in records),'max_arrival_delay_ms':max(r['arrival_delay_ms'] for r in records),'minimum_overlap':min(co_overlaps),'actual_generation_token_counts':'UNAVAILABLE: stored responses expose text, so prediction word count is explicitly a length proxy','GPU_clock_and_thermal_history':'UNAVAILABLE: original telemetry retained utilization/power/memory, not SM clocks or temperature; no retrospective attribution'},'source_classification':'B_INPUT_HETEROGENEITY_SUPPORTED_WITH_INSUFFICIENT_CAUSAL_DECOMPOSITION','evidence':'The nominal same-state repeats each contain only two Phi-ASR observations and six disjoint input IDs, with different audio/generation lengths. Queue/arrival delays and overlap are directly reported. Fixed-input independent full-state replay separates input identity changes from run variation, but six historical samples and absent historical clocks prevent claiming a quantified causal variance share.','unknowns':['Historical co-worker queue/backlog must be inferred from request intervals, not a recorded saturated-backlog64 protocol','Historical thermal/clock changes cannot be recovered','Word counts are proxies rather than exact generated-token counts'],'new_protocol_is_not_old_historical_protocol':True,'no_historical_gate_change':True}
 # More detailed current traces remain raw; summarize observed clock/thermal ranges.
