def summary(anchors,metrics,effects,snr,decision,gate):
 lines=['# Module 9A-2 — Protocol-Matched Repeatability and Noise-Source Audit','',f'执行完成；follow-up gate：**{gate}**。9A-1 gate 永久保持 **GATE_PARTIAL**。','', '## Anchors','']
 for a in anchors:lines.append(f'- {a["anchor"]}: {a["state_keys"]}; '+(f'original Delta-S={a["comparison"]["Delta_S"]}' if 'comparison' in a else 'historical full replica deployment, raw_0070/71/72; fixed replay source raw_0070'))
 lines+=['','## Exact-state run noise','','| State | Mean S | Std | CV | MAD |','|---|---:|---:|---:|---:|']
 for k,m in metrics.items():lines.append(f'| {k} | {m["mean"]:.9f} | {m["std"]:.9f} | {m["CV"]:.9f} | {m["MAD"]:.9f} |')
 lines+=['','## Task effect repeatability','','| Anchor | Mean Delta S | Median | 95% CI | Sign consistency | SNR | Variance ratio |','|---|---:|---:|---|---:|---:|---:|']
 for r in effects:
  a=r['anchor'];lines.append(f'| {a} | {r["mean_Delta_S"]:.9f} | {r["median_Delta_S"]:.9f} | [{r["bootstrap_95CI_low"]:.9f}, {r["bootstrap_95CI_high"]:.9f}] | {r["sign_consistency"]:.3f} | {snr[a]["SNR_effect"]:.6f} | {snr[a]["variance_ratio"]:.6f} |')
 n=load(OUT/'noise_decomposition.json');h=load(OUT/'historical_noise_source_audit.json');d=load(OUT/'ground_truth_protocol_decision.json');lines+=['','## Interpretation and protocol decision','',f'Historical floor={n["historical_noise_floor"]}; current active-pair sigma summary={n["current_active_pair_sigma_summary"]}; historical full-state fixed-input sigma={n["historical_source_fixed_input_sigma"]}. These are different statistics; homologous null Q95 also saved.',f'Historical noisy source: {h["source_classification"]}. Each run had two Phi-ASR requests with six distinct IDs. Audio duration and generation-word proxies, queue/arrival timing, overlap and available telemetry are saved; missing historical clocks/thermal/token counters remain missing.',f'FULL_9A_GROUND_TRUTH_PROTOCOL={decision}; paired bootstrap variance-difference CI={d["variance_difference_95CI"]}. Decision uses variance only, never favorable task significance.',f'FULL_MODULE_9A_RECOMMENDED={gate=="REPEATABILITY_STRONG_SUPPORT"}. Full Module9A, Roomie predictor, v3 search, routing/ranking changes and held-out validation were not started.','', 'All 50 timed runs cold-start independent processes, replay fixed sample IDs and exact warmup counts. A1/A2/A3 share identical standalone/pair states rather than duplicate their measurements. A4 preserves the original multi-model deployment, existing budget, lambda and per-request routing; it is reported separately and is not mislabeled as the current saturated active-pair protocol.','', 'No new benchmark workload/memory point, no automatic runtime retry, and no reclassification of the frozen 9A-1 gate.']
 (OUT/'module9a2_summary.md').write_text('\n'.join(lines)+'\n')
if __name__=='__main__':final()
